inventory.remove_item("apple", 10)
assert inventory.list_items() == {}

inventory = InventoryManager()
inventory.add_item("apple", 10)
try:
    inventory.remove_item("apple", 15)
except ValueError as e:
    assert str(e) == "Not enough of 'apple' in inventory to remove 15 units."

inventory = InventoryManager()
try:
    inventory.remove_item("banana", 5)
except KeyError as e:
    assert str(e) == "Item 'banana' not found in inventory."

inventory = InventoryManager()
