assert sort_nested_dict({'x': {'z': {'b': 2, 'a': 1}}, 'y': 3}) == {'x': {'z': {'a': 1, 'b': 2}}, 'y': 3}

assert sort_nested_dict({'a': {'c': {'e': 5, 'd': 4}, 'b': 3}, 'b': 2}) == {'a': {'b': 3, 'c': {'d': 4, 'e': 5}}, 'b': 2}

assert sort_nested_dict({}) == {}

assert sort_nested_dict({'a': {}}) == {'a': {}}

assert sort_nested_dict({'a': {'b': {'c': {}}}}) == {'a': {'b': {'c': {}}}}

assert sort_nested_dict({'z': 1, 'y': {'x': 2, 'w': {'v': 3, 'u': 4}}}) == {'u': {'v': {'w': 3, 'x': 4}}, 'y': 1, 'z': 2}

