input:
You are tasked with implementing a function `update_config` that processes a JSON configuration object. The function should accept two parameters: a JSON object `config` and a dictionary `updates`. Your goal is to recursively update the `config` object with the values from the `updates` dictionary. If a key in `updates` corresponds to a nested dictionary in `config`, the nested dictionary should be updated accordingly. The function should return the updated JSON object.

**Input:**
- `config`: A JSON object representing the initial configuration.
- `updates`: A dictionary containing the updates to be applied to the configuration.

**Output:**
- The updated JSON object after applying the updates.

**Sample Input:**
```json
config = {"app": {"name": "MyApp", "version": "1.0"}, "server": {"host": "localhost", "port": 8080}}
updates = {"app": {"version": "2.0"}, "server": {"port": 8090}}
```

**Sample Output:**
```json
{
  "app": {
    "name": "MyApp",
    "version": "2.0"
  },
  "server": {
    "host": "localhost",
    "port": 8090
  }
}
```

unit_tests:
assert update_config({"app": {"name": "MyApp", "version": "1.0"}}, {"app": {"version": "2.0"}}) == {"app": {"name": "MyApp", "version": "2.0"}}

assert update_config({"server": {"host": "localhost", "port": 8080}}, {"server": {"port": 8090}}) == {"server": {"host": "localhost", "port": 8090}}

assert update_config({"app": {"name": "MyApp", "version": "1.0"}, "server": {"host": "localhost", "port": 8080}}, {"app": {"version": "2.0"}, "server": {"port": 8090}}) == {"app": {"name": "MyApp", "version": "2.0"}, "server": {"host": "localhost", "port": 8090}}

assert update_config({"app": {"name": "MyApp", "version": "1.0"}}, {"app": {"name": "NewApp"}}) == {"app": {"name": "NewApp", "version": "1.0"}}

assert update_config({"app": {"name": "MyApp", "version": "1.0"}}, {"new_key": "new_value"}) == {"app": {"name": "MyApp", "version": "1.0"}, "new_key": "new_value"}

assert update_config({"app": {"name": "MyApp", "version": "1.0"}}, {}) == {"app": {"name": "MyApp", "version": "1.0"}}

assert update_config({}, {"app": {"name": "MyApp", "version": "1.0"}}) == {"app": {"name": "MyApp", "version": "1.0"}}

assert update_config({"app": {"name": "MyApp", "version": "1.0", "settings": {"theme": "dark"}}}, {"app": {"settings": {"theme": "light"}}}) == {"app": {"name": "MyApp", "version": "1.0", "settings": {"theme": "light"}}}

assert update_config({"app": {"name": "MyApp", "version": "1.0", "settings": {"theme": "dark", "notifications": {"enabled": true}}}}, {"app": {"settings": {"notifications": {"enabled": false}}}}) == {"app": {"name": "MyApp", "version": "1.0", "settings": {"theme": "dark", "notifications": {"enabled": false}}}}

assert update_config({"app": {"name": "MyApp", "version": "1.0", "settings": {"theme": "dark", "notifications": {"enabled": true}}}}, {"app": {"settings": {"theme": "light", "notifications": {"enabled": false}}}}) == {"app": {"name": "MyApp", "version": "1.0", "settings": {"theme": "light", "notifications": {"enabled": false}}}}

