    "mixed": [
        1,
        {
            "key": "value"
        },
        3
    ]
}'

assert convert_to_json({}) == '{}'

assert convert_to_json({"numbers": [1, 2, 3, 4, 5]}) == '{
    "numbers": [
        1,
        2,
        3,
        4,
        5
    ]
}'

