input:
You are given a Python dictionary `data` representing a JSON object. Your task is to convert all keys from snake_case to camelCase without altering the values. The function should handle nested dictionaries and lists of dictionaries. 

**Input:**
- A Python dictionary `data` with keys in snake_case.

**Output:**
- A Python dictionary with keys converted to camelCase.

**Sample Input:**
```python
{
    "first_name": "John",
    "last_name": "Doe",
    "address": {
        "street_name": "123 Main St"
    }
}
```

**Sample Output:**
```python
{
    "firstName": "John",
    "lastName": "Doe",
    "address": {
        "streetName": "123 Main St"
    }
}
```

unit_tests:
assert convert_dict_keys_to_camel({"first_name": "John"}) == {"firstName": "John"}

assert convert_dict_keys_to_camel({"last_name": "Doe", "first_name": "John"}) == {"lastName": "Doe", "firstName": "John"}

assert convert_dict_keys_to_camel({"address": {"street_name": "123 Main St"}}) == {"address": {"streetName": "123 Main St"}}

assert convert_dict_keys_to_camel({"user_info": {"first_name": "John", "last_name": "Doe"}}) == {"userInfo": {"firstName": "John", "lastName": "Doe"}}

assert convert_dict_keys_to_camel({"user_info": {"first_name": "John", "last_name": "Doe", "address": {"street_name": "123 Main St"}}}) == {"userInfo": {"firstName": "John", "lastName": "Doe", "address": {"streetName": "123 Main St"}}}

assert convert_dict_keys_to_camel({"user_info": [{"first_name": "John", "last_name": "Doe"}, {"first_name": "Jane", "last_name": "Doe"}]}) == {"userInfo": [{"firstName": "John", "lastName": "Doe"}, {"firstName": "Jane", "lastName": "Doe"}]}

assert convert_dict_keys_to_camel({"user_info": {"first_name": "John", "last_name": "Doe", "address": {"street_name": "123 Main St", "city_name": "Anytown"}}}) == {"userInfo": {"firstName": "John", "lastName": "Doe", "address": {"streetName": "123 Main St", "cityName": "Anytown"}}}

assert convert_dict_keys_to_camel({"user_info": {"first_name": "John", "last_name": "Doe", "address": {"street_name": "123 Main St", "city_name": "Anytown", "zip_code": "12345"}}}) == {"userInfo": {"firstName": "John", "lastName": "Doe", "address": {"streetName": "123 Main St", "cityName": "Anytown", "zipCode": "12345"}}}

assert convert_dict_keys_to_camel({"user_info": {"first_name": "John", "last_name": "Doe", "address": {"street_name": "123 Main St", "city_name": "Anytown", "zip_code": "12345", "country_name": "USA"}}}) == {"userInfo": {"firstName": "John", "lastName": "Doe", "address": {"streetName": "123 Main St", "cityName": "Anytown", "zipCode": "12345", "countryName": "USA"}}}

assert convert_dict_keys_to_camel({"user_info": {"first_name": "John", "last_name": "Doe", "address": {"street_name": "123 Main St", "city_name": "Anytown", "zip_code": "12345", "country_name": "USA", "phone_number": "555-1234"}}}) == {"userInfo": {"firstName": "John", "lastName": "Doe", "address": {"streetName": "123 Main St", "cityName": "Anytown", "zipCode": "12345", "countryName": "USA", "phoneNumber": "555-1234"}}}

